Given a binary tree, connect the nodes that are at the same level. Given an addition nextRight pointer for the same. Initially, all the next right pointers point to garbage values, set these pointers to the point next right for each node.Examples: Input:Output: Explanation: The above tree represents the nextRight pointer connected the nodes that are at the same level.Try It YourselfTable of ContentUsing Level Order Traversal - O(n) Time and O(n) Space[Expected Approach] Using Already Set Next Rights - O(n) Time and O(1) Space Using Level Order Traversal - O(n) Time and O(n) SpaceThe idea is to use line by line level order traversal, we mainly count nodes at next level using queue size. As nodes are processed, each node's nextRight pointer is set to the next node in the queue.
            C++

    #include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node *left;
    Node *right;
    Node *nextRight;

    Node(int key) {
        data = key;
        left = nullptr;
        right = nullptr;
        nextRight = nullptr;
    }
};

// Connect nodes using node count (level size)
Node* connect(Node *root) {
    if (!root) return root;

    queue<Node*> q;
    q.push(root);

    while (!q.empty()) {
        int nodeCount = q.size();

        for (int i = 0; i < nodeCount; i++) {
            Node* node = q.front();
            q.pop();

            // Set nextRight
            if (i == nodeCount - 1)
                node->nextRight = nullptr;
            else
                node->nextRight = q.front();

            // Push children
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
    }

    return root;
}

int main() {

    // Constructed binary tree
    //       10
    //      /  \
    //    8     2
    //   /     /      
    //  3     4     

    Node *root = new Node(10);
    root->left = new Node(8);
    root->right = new Node(2);
    root->left->left = new Node(3);
    root->right->left = new Node(4);

    connect(root);

    cout << "Next Right of 8 is " << root->left->nextRight->data << endl;
    cout << "Next Right of 3 is " << root->left->left->nextRight->data << endl;

    return 0;
}


